-- Freeze the options for pre-existing pending style gates.
UPDATE app.jobs SET settings=settings || jsonb_build_object('styleOptions', '[{"id": "pedestal_spin", "name": "Pedestal spin", "oneLiner": "A clean product turntable.", "captionPreview": "Made for the moment.", "templateVersion": 1, "prompt": "A single {product} centered on a seamless studio backdrop, slow smooth 360-degree turntable rotation, soft key lighting, shallow depth of field, premium commercial look."}, {"id": "lifestyle_zoom", "name": "Lifestyle zoom", "oneLiner": "A close-up in a natural setting.", "captionPreview": "Small detail, big impact.", "templateVersion": 1, "prompt": "A {product} in a natural lifestyle setting, slow cinematic push-in, warm color grade, bokeh background, aspirational everyday scene."}]'::jsonb)
WHERE state='awaiting_style_choice' AND NOT settings ? 'styleOptions';
